import { Schema } from "mongoose";

import { generalSchemaOptions } from "../../constants/model";
import {
    ACCEPTED_ATTACHMENT_MIME_TYPES,
    EAttachmentStatus,
    IChatAttachment,
} from "../../types/chat-attachment.types";
import { AttachmentTypeEnum } from "../../types/chat.types";

/** Files attached to Viva AI turns. See IChatAttachment. */
const chatAttachmentSchema = new Schema<IChatAttachment>(
    {
        userId: { type: Schema.Types.ObjectId, ref: "users", required: true },
        // Generated by the app per picked file, so a retried upload returns the
        // first record instead of storing the file twice.
        clientUploadId: { type: String, required: true },
        kind: {
            type: String,
            enum: [AttachmentTypeEnum.IMAGE, AttachmentTypeEnum.PDF],
            required: true,
        },
        mimeType: { type: String, enum: ACCEPTED_ATTACHMENT_MIME_TYPES, required: true },
        sizeBytes: { type: Number, required: true },
        sha256: { type: String, required: true },
        width: { type: Number, default: null },
        height: { type: Number, default: null },
        pageCount: { type: Number, default: null },
        // PDFs only, truncated: she recognises "CBC_report.pdf" on the card. Photos
        // get no name, since a camera filename says nothing and may say too much.
        originalName: { type: String, default: null, maxlength: 80 },
        bucket: { type: String, required: true },
        objectName: { type: String, required: true },
        status: {
            type: String,
            enum: Object.values(EAttachmentStatus),
            default: EAttachmentStatus.UPLOADED,
        },
        verdict: {
            type: { code: String, category: String, subject: String },
            default: null,
        },
        conversationId: { type: Schema.Types.ObjectId, default: null },
        messageId: { type: Schema.Types.ObjectId, default: null },
        expiresAt: { type: Date, required: true },
        deletedAt: { type: Date, default: null },
        purgeAt: { type: Date, required: true },
    },
    generalSchemaOptions,
);

chatAttachmentSchema.index({ userId: 1, clientUploadId: 1 }, { unique: true });
chatAttachmentSchema.index({ userId: 1, status: 1, createdAt: -1 });
chatAttachmentSchema.index({ status: 1, createdAt: 1 });
// The record outlives the file by a while so "this file has expired" still resolves,
// then goes too.
chatAttachmentSchema.index({ purgeAt: 1 }, { expireAfterSeconds: 0 });

export default chatAttachmentSchema;
